// Card NEW-20261028-ORQ-uno-capo-fumaca: the smoke out of the Uno's raised hood, 16 frames generated by the Codex on black
// (evidence NEW-20261028-ORQ-uno-capo-fumaca/fumacad16-t6: the brightness became the alpha and each frame was cut by
// gerar/fumaca.py into fumaca-8x2.png). Puts the 16 frames on one 8×2 sheet of FW×FH cells (the source point at the same
// place in every frame), the faint haze under 2 % alpha cleared (no grey film over the street). Prints the sheet's size.
// usage: node scripts/import-uno-fumaca.mjs <fumaca-8x2.png> [out=public/art/lite/veiculos/uno-fumaca.webp] [fw=128] [fh=256]
import sharp from 'sharp';
import {mkdirSync,statSync} from 'node:fs';
import {dirname} from 'node:path';
const [IN,OUT='public/art/lite/veiculos/uno-fumaca.webp',FW_='128',FH_='256']=process.argv.slice(2);const FW=+FW_,FH=+FH_;
if(!IN)throw new Error('usage: node scripts/import-uno-fumaca.mjs <fumaca-8x2.png> [out] [fw] [fh]');
const meta=await sharp(IN).metadata(),cw=meta.width/8,ch=meta.height/2,comp=[];
for(let k=0;k<16;k++){
  const left=Math.round((k%8)*cw),top=Math.round(Math.floor(k/8)*ch),w=Math.round(((k%8)+1)*cw)-left,h=Math.round((Math.floor(k/8)+1)*ch)-top;
  const {data,info}=await sharp(IN).extract({left,top,width:w,height:h}).resize(FW,FH,{kernel:'lanczos3',fit:'fill'}).ensureAlpha().raw().toBuffer({resolveWithObject:true});
  for(let p=3;p<data.length;p+=4)if(data[p]<5)data[p]=0;
  comp.push({input:await sharp(data,{raw:{width:info.width,height:info.height,channels:4}}).png().toBuffer(),left:(k%8)*FW,top:Math.floor(k/8)*FH});
}
mkdirSync(dirname(OUT),{recursive:true});
await sharp({create:{width:8*FW,height:2*FH,channels:4,background:{r:0,g:0,b:0,alpha:0}}}).composite(comp).webp({quality:80,alphaQuality:90,effort:6}).toFile(OUT);
console.log(JSON.stringify({frame:[FW,FH],sheet:[8*FW,2*FH],bytes:statSync(OUT).size}));
